/**
 * The only module, with `stream.ts`, that performs HTTP requests. Components use these functions
 * through TanStack Query and never call `fetch` directly. Request and response bodies come from
 * `schema.d.ts`, generated by `npm run gen:api`; streamed events are typed in `events.ts`.
 */
import type { components } from "@/api/schema";
import { getToken, handleUnauthorized } from "@/auth/store";
import { getConfig } from "@/lib/config";

export type ArticleResponse = components["schemas"]["ArticleResponse"];
export type AskBody = components["schemas"]["AskRequest"];
export type DiscoverBody = components["schemas"]["DiscoverRequest"];
export type FeedbackValue = 1 | -1;

export const SESSION_EXPIRED = "Your session expired. Sign in again.";

export interface ApiErrorBody {
  error: { code: string; message: string; trace_id: string };
}

export class ApiError extends Error {
  readonly status: number;
  readonly code: string;
  readonly traceId: string;

  constructor(status: number, body: ApiErrorBody | null) {
    super(body?.error.message ?? `Request failed with status ${status}`);
    this.status = status;
    this.code = body?.error.code ?? `http_${status}`;
    this.traceId = body?.error.trace_id ?? "";
  }
}

export function authHeaders(): Record<string, string> {
  const token = getToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${getConfig().apiBaseUrl}${path}`, {
    ...init,
    headers: { Accept: "application/json", ...authHeaders(), ...init?.headers },
  });
  if (response.status === 401) handleUnauthorized(SESSION_EXPIRED);
  if (!response.ok) {
    const body = (await response.json().catch(() => null)) as ApiErrorBody | null;
    throw new ApiError(response.status, body);
  }
  if (response.status === 204) return undefined as T;
  return (await response.json()) as T;
}

export function getArticle(pmid: number): Promise<ArticleResponse> {
  return request<ArticleResponse>(`/v1/articles/${pmid}`);
}

export function postFeedback(queryId: number, value: FeedbackValue): Promise<void> {
  const body: components["schemas"]["FeedbackRequest"] = { query_id: queryId, value };
  return request<undefined>("/v1/feedback", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

export type CheckState = "ok" | "fail";

export interface Readiness {
  status: "ok" | "unavailable";
  checks: Record<string, CheckState>;
}

export async function getLiveness(): Promise<boolean> {
  try {
    await request<{ status: "ok" }>("/healthz");
    return true;
  } catch {
    return false;
  }
}

/** Readiness answers 503 with a body when a dependency is down; both cases return data. */
export async function getReadiness(): Promise<Readiness | null> {
  try {
    const response = await fetch(`${getConfig().apiBaseUrl}/readyz`);
    if (response.status !== 200 && response.status !== 503) return null;
    return (await response.json()) as Readiness;
  } catch {
    return null;
  }
}
